 for(const item of cr){assert(item.unitId==='u15'&&item.skillId===skillIds[si]&&item.type==='constructed-response',`${item.questionId}: CR identity`);assert(item.contentAuthority===AUTH&&hashRecord(item)===item.contentSha256,`${item.questionId}: CR hash/authority`);assert(item.rubric.length===4&&item.rubric.map(x=>x.score).sort().join(',')==='0,1,2,3',`${item.questionId}: rubric`);assert(item.standardSolution.length>45&&item.reasoningSteps.length>=3,`${item.questionId}: CR depth`);assert(item.independentReview?.decision==='pass'&&item.independentReview.reviewNote.length>80,`${item.questionId}: CR review`);if(item.figureId)figureRefs.add(item.figureId)}
