for(const [name,arr,key] of [['question IDs',allQ,'questionId'],['CR IDs',allCR,'questionId'],['figure IDs',allD,'figureId']])assert(new Set(arr.map(x=>x[key])).size===arr.length,`duplicate ${name}`);
assert(new Set(allR.map(x=>x.reviewerNote)).size===156,'duplicate reviewer evidence');assert(new Set(allL.map(x=>x.lectureReview.reviewNote)).size===13,'duplicate lecture reviews');assert(new Set(allCR.map(x=>x.independentReview.reviewNote)).size===26,'duplicate CR reviews');
const prompts=[...allQ.map(x=>({id:x.questionId,t:x.text})),...allCR.map(x=>({id:x.questionId,t:x.prompt}))];const normSeen=new Map();for(const p of prompts){const n=normalizePrompt(p.t);if(normSeen.has(n))fail(`normalized duplicate ${p.id} and ${normSeen.get(n)}`);normSeen.set(n,p.id)}
const gs=prompts.map(p=>({id:p.id,g:grams(normalizePrompt(p.t))}));for(let i=0;i<gs.length;i++)for(let j=i+1;j<gs.length;j++){const sim=jaccard(gs[i].g,gs[j].g);if(sim>0.94)fail(`near duplicate ${gs[i].id} ${gs[j].id} ${sim}`)}
