assert(new Set(allCR.map(x=>x.followThroughPolicy)).size===26&&new Set(allCR.map(x=>x.answerOnlyPolicy)).size===26&&new Set(allCR.map(x=>x.unitAndNotationRules)).size===26,'CR policy specificity');
const teachingScope=JSON.stringify({lectures:allL.map(x=>({concept:x.conceptDevelopment,examples:x.workedExamples,mistakes:x.commonMistakes,selfChecks:x.selfChecks})),mc:allQ.map(x=>({text:x.text,choices:x.choices,solution:x.independentSolution,explanation:x.explanation})),cr:allCR.map(x=>({prompt:x.prompt,solution:x.standardSolution,alternative:x.alternativeMethod}))});assert(!/[²]|平方根|二次函數|平方函數/u.test(teachingScope),'out-of-scope non-linear teaching content');
const cm=readJson('manifest/content-sha256.json');assert(cm.schemaVersion==='math-v2-content-sha256-r1'&&cm.records.length===209,'content manifest shape');const expectedContent=[];for(const slot of slots){const base=`units/u15/${slot}`;const l=readJson(`${base}/lecture.json`);expectedContent.push({id:l.lectureId,type:'lecture',path:`${base}/lecture.json`,sha256:l.contentSha256});for(const [file,type] of [['mc-questions.jsonl','mc'],['constructed-response.jsonl','constructed-response'],['drawing-specs.jsonl','figure']])for(const x of readJsonl(`${base}/${file}`))expectedContent.push({id:x.questionId||x.figureId,type,path:`${base}/${file}`,sha256:x.contentSha256})}assert(new Set(cm.records.map(x=>x.id)).size===209,'content manifest duplicate IDs');const cmMap=new Map(cm.records.map(x=>[x.id,x]));for(const e of expectedContent){const got=cmMap.get(e.id);assert(got&&got.type===e.type&&got.path===e.path&&got.sha256===e.sha256,`content manifest mismatch ${e.id}`)}
const fp=readJson('review/unit-content-fingerprints.json');assert(fp.crossUnitComparisonPerformed===false&&fp.fingerprints.length===195,'fingerprint manifest shape');const expectedFp=new Map([...allL.map(x=>[x.lectureId,x.contentSha256]),...allQ.map(x=>[x.questionId,x.contentSha256]),...allCR.map(x=>[x.questionId,x.contentSha256])]);assert(new Set(fp.fingerprints.map(x=>x.id)).size===195,'duplicate fingerprints');for(const e of fp.fingerprints){assert(expectedFp.get(e.id)===e.contentSha256,`fingerprint content hash ${e.id}`);assert(sha(e.normalizedPrompt)===e.normalizedPromptSha256,`fingerprint normalized hash ${e.id}`)}
const standaloneFigureReviews=readJsonl('review/figure-reviews.jsonl');assert(standaloneFigureReviews.length===14&&standaloneFigureReviews.every(x=>x.decision==='pass'&&x.manualInspectionCompleted===true&&x.renderedInspectionSummary?.length>50),'standalone figure reviews');
for(const schema of ['lecture','mc-question','constructed-response','semantic-review','drawing-spec']){const x=readJson(`schemas/${schema}.schema.json`);assert(x.$schema&&x.type==='object'&&Array.isArray(x.required)&&x.required.length>=5,`schema ${schema}`)}
const isolation=readJson('manifest/legacy-content-isolation.json');for(const k of ['legacyContentImported','legacySemanticEvidenceAccepted','oldProductionRuntimeModified','deleteLegacyNow','productionActivationAllowed'])assert(isolation[k]===false,`isolation ${k}`);assert(isolation.finalRetirementRequired===true,'isolation final retirement');
