const fm=readJson('manifest/file-sha256.json');const listed=new Set();for(const e of fm.files){const p=path.join(root,e.path);assert(fs.existsSync(p),`hashed file missing ${e.path}`);assert(sha(fs.readFileSync(p))===e.sha256,`file hash ${e.path}`);listed.add(e.path)}
const walk=d=>fs.readdirSync(d,{withFileTypes:true}).flatMap(e=>{const p=path.join(d,e.name);return e.isDirectory()?walk(p):[p]});const actual=walk(root).map(p=>path.relative(root,p).replaceAll('\\','/')).filter(p=>p!=='manifest/file-sha256.json'&&!p.startsWith('staging/'));for(const p of actual)assert(listed.has(p),`file omitted from manifest ${p}`);assert(listed.size===actual.length,`file manifest size ${listed.size}/${actual.length}`);
